-- Local SQLite migration. Three separate files are attached as main / school / pd.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lead_funnel(id TEXT PRIMARY KEY, direction TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS pd.users(id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','teacher','student','parent')), timezone TEXT NOT NULL DEFAULT 'Europe/Moscow', notifications INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS pd.sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pd.leads(id TEXT PRIMARY KEY, name TEXT NOT NULL, contact TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', request_key TEXT NOT NULL UNIQUE, ip_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pd.responses(id TEXT PRIMARY KEY, student_id TEXT NOT NULL, text TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS pd.reviews(id TEXT PRIMARY KEY, submission_id TEXT NOT NULL, author_id TEXT NOT NULL, text TEXT NOT NULL, decision TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pd.notes(student_id TEXT PRIMARY KEY, text TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS pd.uploads(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, storage_key TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school.guardians(parent_id TEXT NOT NULL, student_id TEXT NOT NULL, PRIMARY KEY(parent_id,student_id));
CREATE TABLE IF NOT EXISTS school.teacher_students(teacher_id TEXT NOT NULL, student_id TEXT NOT NULL, PRIMARY KEY(teacher_id,student_id));
CREATE TABLE IF NOT EXISTS school.groups(id TEXT PRIMARY KEY, title TEXT NOT NULL, teacher_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school.group_members(group_id TEXT NOT NULL REFERENCES groups(id), student_id TEXT NOT NULL, PRIMARY KEY(group_id, student_id));
CREATE TABLE IF NOT EXISTS school.courses(id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, summary TEXT NOT NULL, level TEXT NOT NULL DEFAULT 'A1', audience TEXT NOT NULL DEFAULT 'Не уточнена', topic TEXT NOT NULL DEFAULT 'Начало', format TEXT NOT NULL DEFAULT 'Самостоятельный демомодуль', status TEXT NOT NULL DEFAULT 'preparing', publication TEXT NOT NULL DEFAULT 'draft', demo INTEGER NOT NULL DEFAULT 0, owner_id TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS school.modules(id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), title TEXT NOT NULL, position INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS school.lessons(id TEXT PRIMARY KEY, module_id TEXT NOT NULL REFERENCES modules(id), title TEXT NOT NULL, goal TEXT NOT NULL, blocks TEXT NOT NULL CHECK(json_valid(blocks)), exercises TEXT NOT NULL CHECK(json_valid(exercises)), homework TEXT NOT NULL DEFAULT '', teacher_notes TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL, publication TEXT NOT NULL DEFAULT 'draft', version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS school.entitlements(id TEXT PRIMARY KEY, student_id TEXT NOT NULL, course_id TEXT NOT NULL REFERENCES courses(id), source TEXT NOT NULL, granted_by TEXT NOT NULL, expires_at TEXT, revoked_at TEXT, UNIQUE(student_id,course_id,source));
CREATE TABLE IF NOT EXISTS school.completions(student_id TEXT NOT NULL, lesson_id TEXT NOT NULL REFERENCES lessons(id), created_at TEXT NOT NULL, PRIMARY KEY(student_id,lesson_id));
CREATE TABLE IF NOT EXISTS school.attempts(id TEXT PRIMARY KEY, student_id TEXT NOT NULL, lesson_id TEXT NOT NULL, exercise_id TEXT NOT NULL, exercise_version INTEGER NOT NULL, answers TEXT NOT NULL, score INTEGER, feedback TEXT NOT NULL, request_key TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(student_id,request_key));
CREATE TABLE IF NOT EXISTS school.submissions(id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL, student_id TEXT NOT NULL, attempt_no INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','submitted','returned','checked')), upload_id TEXT, due_at TEXT, submitted_at TEXT, version INTEGER NOT NULL DEFAULT 1, UNIQUE(lesson_id,student_id,attempt_no));
CREATE TABLE IF NOT EXISTS school.events(id TEXT PRIMARY KEY, title TEXT NOT NULL, teacher_id TEXT NOT NULL, student_id TEXT, group_id TEXT, starts_at TEXT NOT NULL, timezone TEXT NOT NULL, meeting_url TEXT, status TEXT NOT NULL DEFAULT 'scheduled');
CREATE TABLE IF NOT EXISTS school.materials(id TEXT PRIMARY KEY, source_id TEXT NOT NULL, relative_path TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', description_source TEXT NOT NULL, format TEXT NOT NULL DEFAULT '', bytes INTEGER, checksum TEXT, processing TEXT CHECK(processing IN ('unprocessed','partial','full') OR processing IS NULL), legacy_processed TEXT, editorial TEXT NOT NULL DEFAULT 'unchecked', publication TEXT NOT NULL DEFAULT 'draft', rights TEXT NOT NULL DEFAULT 'unknown', privacy TEXT NOT NULL DEFAULT 'internal', topic TEXT NOT NULL DEFAULT '', level TEXT NOT NULL DEFAULT '', audience TEXT NOT NULL DEFAULT '', skills TEXT NOT NULL DEFAULT '', instructions TEXT NOT NULL DEFAULT '', related TEXT NOT NULL DEFAULT '[]', storage_key TEXT, missing INTEGER NOT NULL DEFAULT 1, UNIQUE(source_id,relative_path));
CREATE TABLE IF NOT EXISTS school.lesson_materials(lesson_id TEXT NOT NULL REFERENCES lessons(id), material_id TEXT NOT NULL REFERENCES materials(id), PRIMARY KEY(lesson_id,material_id));
CREATE TABLE IF NOT EXISTS school.favorites(student_id TEXT NOT NULL, material_id TEXT NOT NULL REFERENCES materials(id), PRIMARY KEY(student_id,material_id));
CREATE TABLE IF NOT EXISTS school.import_runs(id TEXT PRIMARY KEY, source_id TEXT NOT NULL, digest TEXT NOT NULL, report TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS school.entitlements_student ON entitlements(student_id,course_id,revoked_at);
CREATE INDEX IF NOT EXISTS school.submissions_status ON submissions(status,student_id);
CREATE INDEX IF NOT EXISTS school.materials_catalog ON materials(publication,rights,editorial,topic);
CREATE INDEX IF NOT EXISTS school.lessons_module ON lessons(module_id,position);
CREATE INDEX IF NOT EXISTS pd.leads_rate ON leads(ip_hash,created_at);
INSERT OR IGNORE INTO schema_migrations VALUES(1,datetime('now'));
